pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    AccessControlMock mock;
    bool inited;

    function setUp() public {
        c = new C();
        mock = new AccessControlMock();
    }

    function testFuzz_property(address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        vm.assume(asset != address(0));
        kink = bound(kink, 1, 1e27 - 1);

        // 1. drive c through `initialize` exactly once with the (adversarial) access-control party
        if (!inited) {
            try c.initialize(address(mock)) {
                inited = true;
            } catch {
                inited = false;
            }
        }

        // 2. with correct initialization, a valid, access-checked setSlopes call must succeed
        bool ok = false;
        if (inited) {
            C.SlopeData memory slopes = C.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
            try c.setSlopes(asset, slopes) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // 3. general rule: initialization + an authorized guarded write succeed for every input
        assertTrue(ok);
    }
}

