pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    bytes32 constant IMPL_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        AccessMock ac = new AccessMock();
        UUPSProxy proxy = new UUPSProxy(address(c));

        // initialize through the proxy (direct initialize on the implementation is disabled by its constructor)
        (bool okInit, ) = address(proxy).call(abi.encodeWithSelector(C.initialize.selector, address(ac)));
        assertTrue(okInit, "initialize must succeed with a real access-control contract");

        uint256[] memory none = new uint256[](0);
        (bool ok, ) = address(proxy).call(abi.encodeWithSelector(IVaultAdapter.setLimits.selector, 1, 1, 1));
        ok; // silence unused

        // any caller may perform an access-controlled setLimits: P succeeds, M (stores address(0)) reverts
        vm.prank(actor);
        (bool okLimits, ) = address(proxy).call(abi.encodeWithSelector(IVaultAdapter.setLimits.selector, 5e26, 1e26, 1e18));
        assertTrue(okLimits, "setLimits must succeed after proper initialization for any caller");
    }
}

contract AccessMock {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

contract UUPSProxy {
    constructor(address impl) {
        assembly {
            sstore(0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc, impl)
        }
    }

    fallback() external payable {
        assembly {
            let ptr := mload(0x40)
            calldatacopy(ptr, 0, calldatasize())
            let result := delegatecall(gas(), sload(0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc), ptr, calldatasize(), 0, 0)
            returndatacopy(ptr, 0, returndatasize())
            switch result
            case 0 { revert(ptr, returndatasize()) }
            default { return(ptr, returndatasize()) }
        }
    }
}

