pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, uint256 kink, uint256 slope0, uint256 slope1) public {
        vm.assume(caller != address(0));
        // Deploy a functioning access-control contract that grants every access check.
        GrantingAccessControl ac = new GrantingAccessControl();
        ac.initialize(address(this));
        // Initialize the adapter through its public entry point with the real access control.
        c.initialize(address(ac));

        // Keep the slope payload admissible: 0 < kink < 1e27, otherwise setSlopes
        // reverts for its own reasons on BOTH versions and cannot witness the bug.
        kink = bound(kink, 1, 1e27 - 1);
        slope0 = bound(slope0, 0, 1e30);
        slope1 = bound(slope1, 0, 1e30);

        // Drive the adapter through an access-controlled entry point with a fuzzed caller.
        C.SlopeData memory slopes = C.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
        vm.prank(caller);
        bool ok;
        try c.setSlopes(address(0x1234), slopes) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: with a properly stored, functioning access-control contract,
        // setSlopes succeeds for ANY caller and any admissible slope payload.
        // The mutant stored address(0) as accessControl, so the checkAccess low-level
        // call hits an empty-code target and every setSlopes call reverts.
        assertTrue(ok);
    }
}

contract GrantingAccessControl {
    function initialize(address) external {}
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
    function grantAccess(bytes4, address, address) external {}
    function revokeAccess(bytes4, address, address) external {}
    function role(bytes4, address) external pure returns (bytes32) {
        return bytes32(0);
    }
}

