pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    struct SlopeData {
        uint256 kink;
        uint256 slope0;
        uint256 slope1;
    }

    interface IVA {
        function initialize(address) external;
        function setSlopes(address, SlopeData memory) external;
    }

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        kink = bound(kink, 1, 1e27 - 1); // admissible kink: 0 < kink < 1e27
        vm.assume(actor != address(0));

        // Adversarial access control: checkAccess always reverts with a custom error.
        RevertingAccessControl ac = new RevertingAccessControl();

        vm.prank(actor);
        c.initialize(address(ac));

        SlopeData memory slopes = SlopeData({kink: kink, slope0: slope0, slope1: slope1});

        (bool ok, bytes memory returndata) =
            address(c).call(abi.encodeWithSelector(C.setSlopes.selector, asset, slopes));
        ok; // the access control always reverts, so the call reverts in both versions

        // General rule: the revert from the configured access-control contract propagates
        // through c with its payload intact (>= 4 bytes of custom-error data).
        // The mutant stores address(0), so the check hits an address with no code and
        // c reverts with an EMPTY payload.
        assertTrue(returndata.length >= 4, "access-control revert payload must propagate through c");
    }
}

contract RevertingAccessControl {
    error AccessRejected();

    function checkAccess(bytes4, address, address) external pure {
        revert AccessRejected();
    }
}

