pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address admin) public {
        vm.assume(admin != address(0));
        bool firstOk;
        try c.initialize(admin) {
            firstOk = true;
        } catch {
            firstOk = false;
        }
        assertTrue(firstOk, "first initialize should succeed");

        // General rule: after a successful initialize, any further initialize reverts.
        bool secondOk;
        try c.initialize(admin) {
            secondOk = true;
        } catch {
            secondOk = false;
        }
        assertTrue(!secondOk, "re-initialization must be impossible");
    }
}
